      "timeoutMs": 30000
    },
    {
      "id": "V2",
      "argv": [
        "node",
        "-e",
        "const fs=require('fs');const s=fs.readFileSync('README_ko.md','utf8');if(!/Operator 인증키|Operator 키/.test(s)||!/Office 화면|로컬 Operator 기능|작업 관리/.test(s)||!/인스턴스/.test(s)||!/모델 호출 권한|구독 로그인/.test(s))process.exit(1);"
      ],
      "timeoutMs": 30000
    },
    {
      "id": "V3",
      "argv": [
        "node",
        "-e",
        "const fs=require('fs');const s=fs.readFileSync('README_ko.md','utf8');if(!/Codex 구독 로그인|구독 로그인/.test(s)||!/실제 모델 호출/.test(s)||!/별도 인증|분리/.test(s)||!/Operator/.test(s))process.exit(1);"
      ],
      "timeoutMs": 30000
    },
    {
      "id": "V4",
      "argv": [
        "node",
        "-e",
        "const fs=require('fs');const s=fs.readFileSync('README_ko.md','utf8');if(!/Mac controller|macOS controller|controller/.test(s)||!/기존 Codex 로그인|기존 로그인/.test(s)||!/전용 VM/.test(s)||!/파일.*명령|명령.*파일/.test(s))process.exit(1);"
      ],
      "timeoutMs": 30000
    },
    {
      "id": "V5",
      "argv": [
        "node",
        "-e",
        "const fs=require('fs');const s=fs.readFileSync('README_ko.md','utf8');if(!/\\[[^\\]]*(작업 관리|Operator|실행 안내|인증키)[^\\]]*\\]\\(docs\\/LOCAL-PREVIEW\\.md(?:#[^)]+)?\\)/.test(s))process.exit(1);"
      ],
      "timeoutMs": 30000
