      ],
      "timeoutMs": 30000
    },
    {
      "id": "V7",
      "argv": [
        "bash",
        "-lc",
        "! git diff -- README_ko.md | grep -E 'approval-decide|approval-request|npm publish|배포|계정 변경|구독 변경|docs/LOCAL-PREVIEW.md'"
      ],
      "timeoutMs": 30000
    }
  ],
  "workspace": {
    "include": [
      "README_ko.md"
    ],
    "exclude": []
  }
