{
  "version": 1,
  "checks": [
    {
      "id": "V1",
      "argv": [
        "node",
        "-e",
        "const fs=require('fs'); if(!fs.existsSync('README_ko.md')) throw new Error('README_ko.md missing'); if(!fs.existsSync('docs/LOCAL-PREVIEW.md')) throw new Error('docs/LOCAL-PREVIEW.md missing'); const text=fs.readFileSync('README_ko.md','utf8'); const links=[...text.matchAll(/\\[[^\\]]*\\]\\((docs\\/LOCAL-PREVIEW\\.md(?:#[^)]+)?)\\)/g)].map(m=>m[1]); if(links.length===0) throw new Error('README_ko.md must link to docs/LOCAL-PREVIEW.md'); console.log('Reviewer must additionally confirm Office baseline diff changes README_ko.md only and no LOCAL-PREVIEW content was copied into a new section.');"
      ],
      "timeoutMs": 30000
    },
    {
      "id": "V2",
      "argv": [
        "node",
        "-e",
        "const fs=require('fs'); const text=fs.readFileSync('README_ko.md','utf8'); if(!/Operator\\s*(인증키|키)|Operator/.test(text)) throw new Error('Operator key wording missing'); if(!/Office|화면|로컬 Operator/.test(text)) throw new Error('Office/operator purpose missing'); if(!/Codex/.test(text) || !/(구독|계정).*로그인|로그인.*(구독|계정)/.test(text)) throw new Error('Codex subscription login boundary missing'); if(!/(아니|별개|분리|다르)/.test(text)) throw new Error('separation wording missing');"
      ],
      "timeoutMs": 30000
    },
    {
      "id": "V3",
      "argv": [
        "node",
        "-e",
        "const fs=require('fs'); const text=fs.readFileSync('README_ko.md','utf8'); for (const re of [/Mac\\s*controller|Mac.*컨트롤러|macOS.*controller/i, /기존.*로그인|로그인.*사용/, /(파일|명령).*도구|도구.*(파일|명령)/, /전용\\s*VM|VM/]) { if(!re.test(text)) throw new Error('missing structure wording: '+re); }"
      ],
      "timeoutMs": 30000
    },
    {
      "id": "V4",
      "argv": [
        "node",
        "-e",
        "const fs=require('fs'); const text=fs.readFileSync('README_ko.md','utf8'); const banned=[/공개\\s*모델\\s*실행[^\\n.]{0,30}(완료|가능|제공|검증됨)/,/전체\\s*실제\\s*사용\\s*검증[^\\n.]{0,30}(완료|통과|검증됨)/,/자동\\s*승인\\s*생성|승인\\s*생성[^\\n.]{0,20}(완료|제공|가능)/,/배포[^\\n.]{0,20}(완료|됨|제공)/,/계정\\s*변경[^\\n.]{0,20}(완료|됨|제공)/]; for (const re of banned) { if(re.test(text)) throw new Error('overclaiming wording matched: '+re); }"
      ],
      "timeoutMs": 30000
    },
    {
      "id": "V5",
      "argv": [
        "node",
        "-e",
        "const fs=require('fs'); const text=fs.readFileSync('README_ko.md','utf8'); const link=/\\[[^\\]]*(작업 관리|Operator|실행 안내|로컬 미리보기)[^\\]]*\\]\\(docs\\/LOCAL-PREVIEW\\.md(?:#[^)]+)?\\)/; const nearby=/docs\\/LOCAL-PREVIEW\\.md[\\s\\S]{0,80}(작업 관리|Operator)|(?:작업 관리|Operator)[\\s\\S]{0,120}docs\\/LOCAL-PREVIEW\\.md/; if(!link.test(text) && !nearby.test(text)) throw new Error('LOCAL-PREVIEW link must be in 작업 관리 or Operator context');"
      ],
      "timeoutMs": 30000
    }
  ],
  "workspace": {
    "include": [
      "README_ko.md",
      "docs/LOCAL-PREVIEW.md"
    ],
    "exclude": []
  }
}
